mapper.select:
select id, user_id, optimization_count, success_count, total_duration, last_optimization_time, create_time, update_time
from sys_user_optimization
where user_id = #{userId}

mapper.update:
update sys_user_optimization
set optimization_count = #{optimizationCount},
    success_count = #{successCount},
    total_duration = #{totalDuration},
    last_optimization_time = #{lastOptimizationTime}
where user_id = #{userId}
